const { useEffect, useRef, useState } = React;

const STOPS = "#FFF6B7 10%, #F6416C 100%";
const FALLBACK = "to right";
// kind 为规范上的匹配结果；angle 为生效时渐变朝向，用于画方向箭头
const PRESETS = [
  { value: "0", kind: "<zero>", valid: true, angle: 0 },
  { value: "0deg", kind: "<angle>", valid: true, angle: 0 },
  { value: "calc(0deg)", kind: "<angle>（calc 结果带单位）", valid: true, angle: 0 },
  { value: "to top", kind: "to <side-or-corner>", valid: true, angle: 0 },
  { value: "calc(0)", kind: "<number>，计算值不是字面量 0", valid: false },
  { value: "0px", kind: "<length>，不是角度", valid: false },
  { value: "90", kind: "<number>，只有 0 能省单位", valid: false },
];

const gradientOf = direction => `linear-gradient(${direction}, ${STOPS})`;

// 浏览器能检测时以实测为准，否则回退到规范结论
const supports = direction => {
  if (typeof CSS === "undefined" || typeof CSS.supports !== "function") return null;
  return CSS.supports("background-image", gradientOf(direction));
};

const Chip = ({ children }) => (
  <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{children}</code>
);

const Row = ({ label, children }) => (
  <div className="flex min-w-0 flex-col gap-1">
    <span className="text-tau-sm text-ink-3">{label}</span>
    <div className="min-w-0">{children}</div>
  </div>
);

const Component = () => {
  const tileRef = useRef(null);
  const [selected, setSelected] = useState("0");
  const [custom, setCustom] = useState("");

  const direction = custom.trim() || selected;
  const preset = custom.trim() ? null : PRESETS.find(item => item.value === selected);
  const measured = supports(direction);
  const valid = measured ?? preset?.valid ?? null;
  const angle = valid === false ? 90 : preset?.angle;

  // 真实走一遍层叠：先写回退值再写候选值，无效的候选值会被浏览器整条丢弃
  useEffect(() => {
    const tile = tileRef.current;
    tile.style.backgroundImage = gradientOf(FALLBACK);
    tile.style.backgroundImage = gradientOf(direction);
  }, [direction]);

  const choose = value => {
    setCustom("");
    setSelected(value);
  };

  return (
    <div className="@container flex flex-col gap-3">
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,42%)]">
        <div className="flex flex-col items-center justify-center gap-3 rounded-tau-md border border-line-1 p-4">
          <div ref={tileRef} className="relative grid size-[150px] place-items-center rounded-tau-md shadow-card">
            {angle !== undefined && (
              <span className="grid size-10 place-items-center rounded-full bg-surface/80 text-ink-1 shadow-card">
                <icons.ArrowUp className="size-5 transition-transform duration-300 ease-tau-out" style={{ transform: `rotate(${angle}deg)` }} />
              </span>
            )}
          </div>
          <span className="text-center text-tau-sm text-ink-3">
            {valid === false ? `回退到上一条声明：${FALLBACK}` : "箭头为渐变方向"}
          </span>
        </div>
        <div className="flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-3">
          <Row label="声明">
            <code className="block min-w-0 break-all font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
              background-image: linear-gradient(
              <span className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">{direction}</span>, …);
            </code>
          </Row>
          {preset && (
            <Row label="匹配">
              <Chip>{preset.kind}</Chip>
            </Row>
          )}
          <Row label="结果">
            {valid === null ? (
              <span className="text-tau-body text-ink-3">当前环境无法检测</span>
            ) : valid ? (
              <span className="inline-flex items-center gap-1.5 rounded-full bg-ok-soft px-2.5 py-0.5 text-tau-meta text-ok">
                <icons.Check className="size-3.5" />
                声明生效
              </span>
            ) : (
              <span className="inline-flex items-center gap-1.5 rounded-full bg-danger-soft px-2.5 py-0.5 text-tau-meta text-danger">
                <icons.X className="size-3.5" />
                整条声明被丢弃
              </span>
            )}
          </Row>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-2">
        {PRESETS.map(item => {
          const active = !custom.trim() && selected === item.value;
          return (
            <button
              key={item.value}
              type="button"
              aria-pressed={active}
              onClick={() => choose(item.value)}
              className={`cursor-pointer rounded-tau-sm border px-2.5 py-1 font-tau-mono text-tau-sm transition-colors ${
                active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
              }`}
            >
              {item.value}
            </button>
          );
        })}
        <ui.Input
          size="sm"
          clearable
          wrapperClassName="w-[180px]"
          placeholder="自己试，如 0turn"
          aria-label="自定义方向"
          value={custom}
          onChange={event => setCustom(event.target.value)}
        />
      </div>
    </div>
  );
};
